#include <iostream>
#include <vector>

int main() {
    // 4096 symbols x 4096 ticks of prices in ticks, in one block.
    // Row s (one symbol's day) starts at element s * n.
    const int n = 4096;
    std::vector<int> prices(n * n);
    for (int i = 0; i < n * n; ++i) {
        prices[i] = 100 + i % 7;
    }

    long long byRows = 0;  // symbol by symbol: next address every step
    for (int s = 0; s < n; ++s) {
        for (int t = 0; t < n; ++t) {
            byRows += prices[s * n + t];
        }
    }

    long long byColumns = 0;  // tick by tick: jumps n * 4 bytes every step
    for (int t = 0; t < n; ++t) {
        for (int s = 0; s < n; ++s) {
            byColumns += prices[s * n + t];
        }
    }

    std::cout << "bytes: " << prices.size() * sizeof(int) << '\n';
    std::cout << "by rows: " << byRows << '\n';
    std::cout << "by columns: " << byColumns << '\n';
    return 0;
}

