#include <iostream>
#include <string>
#include <vector>

// A model cache: 512 slots that hold one 64-byte line each, 32 KB in all.
// Line number L can only go in slot L % 512, like the simplest real caches.
const long kLineBytes = 64;
const long kSlots = 512;
std::vector<long> g_slots(kSlots, -1);  // the line in each slot, -1 for none
long g_reads = 0;
long g_misses = 0;

void cacheRead(long address) {
    ++g_reads;
    long line = address / kLineBytes;
    long slot = line % kSlots;
    if (g_slots[slot] != line) {
        ++g_misses;  // a miss: fetch the line from the next level down
        g_slots[slot] = line;
    }
}

void report(const std::string& name) {
    std::cout << name << ": " << g_reads << " reads, " << g_misses << " misses\n";
    g_reads = 0;
    g_misses = 0;
}

int main() {
    const long n = 256;  // a 256 x 256 grid of 4-byte ints, 256 KB
    for (long r = 0; r < n; ++r) {
        for (long c = 0; c < n; ++c) {
            cacheRead((r * n + c) * 4);
        }
    }
    report("by rows");

    for (long c = 0; c < n; ++c) {
        for (long r = 0; r < n; ++r) {
            cacheRead((r * n + c) * 4);
        }
    }
    report("by columns");
    return 0;
}

