#include <iostream>
#include <sys/resource.h>  // getrusage, on Linux and macOS
#include <unistd.h>        // sysconf

// Minor page faults so far: first touches of pages the kernel had to map.
long pageFaults() {
    rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    return usage.ru_minflt;
}

// Fault counts vary a little from run to run, so print a rough size.
const char* howMany(long faults) {
    if (faults == 0) {
        return "none";
    }
    return faults < 10 ? "a few" : "many";
}

int main() {
    const long page = sysconf(_SC_PAGESIZE);
    const long n = 40'000'000;  // 40 MB
    std::cout << "page size a multiple of 4096: " << (page % 4096 == 0 ? "yes" : "no") << '\n';

    long before = pageFaults();
    char* block = new char[n];  // address space: no pages mapped yet
    std::cout << "new: " << howMany(pageFaults() - before) << '\n';

    before = pageFaults();
    for (long i = 0; i < n; i += page) {
        block[i] = 1;  // the first write to each page
    }
    std::cout << "first pass: " << howMany(pageFaults() - before) << '\n';

    before = pageFaults();
    for (long i = 0; i < n; i += page) {
        block[i] = 2;  // every page is mapped now
    }
    std::cout << "second pass: " << howMany(pageFaults() - before) << '\n';
    delete[] block;
    return 0;
}

