#include <iostream>
#include <sys/resource.h>  // getrusage, on Linux and macOS
#include <vector>

// Minor page faults so far: first touches of pages the kernel had to map.
long pageFaults() {
    rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    return usage.ru_minflt;
}

// Fault counts vary a little from run to run, so print a rough size.
const char* howMany(long faults) {
    if (faults == 0) {
        return "none";
    }
    return faults < 10 ? "a few" : "many";
}

int main() {
    const long count = 5'000'000;  // 5000000 longs, 40 MB
    const long bytes = count * static_cast<long>(sizeof(long));
    std::cout << count << " longs = " << bytes << " bytes\n";

    std::vector<long> fills;
    long before = pageFaults();
    fills.reserve(count);
    std::cout << "reserve: " << howMany(pageFaults() - before) << '\n';

    before = pageFaults();
    for (long i = 0; i < count; ++i) {
        fills.push_back(i);
    }
    std::cout << "first fill: " << howMany(pageFaults() - before) << '\n';

    fills.clear();  // size 0, the capacity and its pages stay
    before = pageFaults();
    for (long i = 0; i < count; ++i) {
        fills.push_back(i);
    }
    std::cout << "refill after clear: " << howMany(pageFaults() - before) << '\n';
    return 0;
}

