#include <cstddef>
#include <iostream>
#include <string>
#include <vector>

// A typical x86-64 server, smallest and fastest level first.
const long long KB = 1024;
const std::vector<std::string> kLevel = {"L1", "L2", "L3", "RAM", "SSD"};
const std::vector<long long> kBytes = {
    48 * KB,                // 48 KB per core
    2 * KB * KB,            // 2 MB per core
    32 * KB * KB,           // 32 MB shared by all cores
    256 * KB * KB * KB,     // 256 GB
    4 * KB * KB * KB * KB,  // 4 TB
};
const std::vector<long long> kNanos = {1, 4, 15, 100, 50'000};  // one random read

// Prints the smallest level that holds the whole data set.
void place(const std::string& name, long long bytes) {
    for (std::size_t i = 0; i < kLevel.size(); ++i) {
        if (bytes <= kBytes[i]) {
            std::cout << name << " (" << bytes << " bytes): " << kLevel[i]
                      << ", about " << kNanos[i] << " ns a random read\n";
            return;
        }
    }
    std::cout << name << " (" << bytes << " bytes): bigger than one machine\n";
}

int main() {
    place("top of book, 100 levels", 100 * 2 * 16);  // two sides, 16 bytes a level
    place("today's orders", 1'500'000);
    place("500 symbols' books", 20'000'000);
    place("one symbol's ticks today", 200'000'000);
    place("ten years of ticks", 2'000'000'000'000LL);
    return 0;
}

