const std::vector<std::string> kLevel = {"L1", "L2", "RAM", "SSD"};
const std::vector<long long> kBytes = {
    128 * KB,               // 128 KB
    16 * KB * KB,           // 16 MB
    16 * KB * KB * KB,      // 16 GB, a laptop's RAM
    KB * KB * KB * KB,      // 1 TB
};
const std::vector<long long> kNanos = {1, 5, 100, 50'000};  // one random read

// Prints the smallest level that holds the whole data set.
void place(const std::string& name, long long bytes) {
    for (std::size_t i = 0; i < kLevel.size(); ++i) {
        if (bytes <= kBytes[i]) {
            std::cout << name << " (" << bytes << " bytes): " << kLevel[i]
                      << ", about " << kNanos[i] << " ns a random read\n";
            return;
        }
    }
    std::cout << name << " (" << bytes << " bytes): bigger than one machine\n";
}

int main() {
    place("a lookup table", 64 * 1024);
    place("an order book's levels", 8'000'000);
    place("a tick buffer", 20'000'000);
    place("a backtest's data", 30'000'000'000LL);
